import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    points = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]

    x_coords = sorted(set(x for x, y in points))
    y_coords = sorted(set(y for x, y in points))

    grid_points = set(points)
    for x in x_coords:
        for y in y_coords:
            if (x, y) not in grid_points:
                grid_points.add((x, y))

    result = list(grid_points)
    result.sort(key=lambda p: (p[0], p[1]))

    print(len(result))
    for x, y in result:
        print(x, y)

if __name__ == "__main__":
    main()
